ALTER TABLE public.social_rules ADD COLUMN duration_minutes integer NOT NULL DEFAULT 45 CHECK(duration_minutes>0), ADD COLUMN activity_energy_cost integer NOT NULL DEFAULT 5 CHECK(activity_energy_cost>=0), ADD COLUMN activity_relation_gain integer NOT NULL DEFAULT 10, ADD COLUMN activity_reputation_gain integer NOT NULL DEFAULT 3, ADD COLUMN activity_influence_gain integer NOT NULL DEFAULT 1;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.social_interact(uuid,text)'::regprocedure) INTO def; def:=replace(def,'start_at+interval ''45 minutes''','start_at+rule.duration_minutes*interval ''1 minute'''); def:=replace(def,'n.location_id,5,n.id,10,3,1,','n.location_id,rule.activity_energy_cost,n.id,rule.activity_relation_gain,rule.activity_reputation_gain,rule.activity_influence_gain,'); EXECUTE def; END $$;
COMMENT ON TABLE public.social_rules IS 'Authoritative configurable interaction and invitation values; src/game/social.ts holds presentation helpers, never authorizes rewards.';